 const{palette}=useAppTheme(),{width}=useWindowDimensions(),desktop=Platform.OS==='web'&&width>=900,expoGo=Constants.executionEnvironment==='storeClient',refreshToken=useAuth(x=>x.refreshToken),{securityCheck}=useLocalSearchParams<{securityCheck?:string}>();const[data,setData]=useState<SecurityData|null>(null),[loading,setLoading]=useState(true),[expanded,setExpanded]=useState<string|null>(null),[verify,setVerify]=useState<'email'|'phone'|null>(null),[challenge,setChallenge]=useState(''),[code,setCode]=useState(''),[verifying,setVerifying]=useState(false),[biometric,setBiometric]=useState(false),[bioBusy,setBioBusy]=useState(false);
